```php
<?php

/**
 * @template-covariant A
 * @psalm-immutable
 */
final class Maybe
{
    /**
     * @param null|A $value
     */
    private function __construct(private bool $isJust, private $value = null) {}


    /**
     * @template B
     * @param B $value
     * @return Maybe<B>
     *
     * @psalm-pure
     */
    public static function just($value): self
    {
        return new self(true, $value);
    }

    /**
     * @template B
     * @return Maybe<B>
     *
     * @psalm-pure
     */
    public static function nothing(): self
    {
        return new self(false);
    }
}

abstract class StringValue
{
    final private function __construct(private readonly string $value) {}

    /** @return Maybe<static> */
    final public static function tryFrom(string $value): Maybe
    {
        return static::isValid($value)
            ? Maybe::just(new static($value))
            : Maybe::nothing();
    }

    abstract protected static function isValid(string $value): bool;
}
```

